"""Confirmed worldwide gaming events, cons, showcases, sports, films, and OTT (2022–2026).

Rows use actual runtimes (start_date → end_date). Theatrical films keep a two-week
opening window; weekly series use premiere→finale; binge drops are one day.
"""

from __future__ import annotations

from datetime import date, timedelta

MEDIA_EVENT_TYPES = {
    "Theatrical Film",
    "Animated Film",
    "OTT Film",
    "OTT Series",
    "Animated Series",
    "Anime Series",
    "Podcast / Audio",
    "OTT Special",
}


def _row(
    name: str,
    start: date,
    end: date,
    *,
    category: str,
    related_game: str,
    event_type: str,
    location: str = "",
    organizer: str = "",
    mode: str = "hybrid",
    wiki: str = "",
    summary: str = "",
    cadence: str = "annual",
    scope: str = "",
) -> dict:
    if end < start:
        end = start
    if not scope:
        scope = "global" if location in ("Online", "Worldwide", "Global", "Worldwide theatrical") else "regional"
    return {
        "kind": "event",
        "start_date": start.isoformat(),
        "end_date": end.isoformat(),
        "date_precision": "day",
        "event": name,
        "category": category,
        "related_game": related_game,
        "event_type": event_type,
        "status": "Confirmed",
        "wikipedia_url": f"https://en.wikipedia.org/wiki/{wiki}" if wiki else "",
        "source": "historical_registry",
        "confirmation": "confirmed",
        "official_source": "Wikipedia year pages / organizer calendars 2022–2026",
        "summary": summary or f"{name} ran {start.isoformat()} → {end.isoformat()}.",
        "attendance_mode": mode,
        "scope": scope,
        "location": location,
        "organizer": organizer,
        "cadence": cadence,
    }


def _film(name: str, opening: date, related: str, distributor: str, wiki: str, *, days: int = 14, animated: bool = False) -> dict:
    end = opening + timedelta(days=days - 1)
    return _row(
        name,
        opening,
        end,
        category="Movies",
        related_game=related,
        event_type="Animated Film" if animated else "Theatrical Film",
        location="Worldwide theatrical",
        organizer=distributor,
        mode="physical",
        wiki=wiki,
        summary=f"US/wide theatrical opening {opening.isoformat()} with a {days}-day merchandising runtime.",
        cadence="one-off",
        scope="global",
    )


def _ott(
    name: str,
    start: date,
    related: str,
    distributor: str,
    wiki: str,
    *,
    end: date | None = None,
    event_type: str = "OTT Series",
    category: str = "OTT",
) -> dict:
    finish = end or start
    return _row(
        name,
        start,
        finish,
        category=category,
        related_game=related,
        event_type=event_type,
        location="Online",
        organizer=distributor,
        mode="digital",
        wiki=wiki,
        summary=(
            f"Streaming premiere {start.isoformat()}"
            + (f" through {finish.isoformat()}" if finish != start else " (same-day drop).")
        ),
        cadence="one-off",
        scope="global",
    )


def _records() -> list[dict]:
    rows: list[dict] = []
    rows.extend(_industry_events())
    rows.extend(_showcases())
    rows.extend(_esports())
    rows.extend(_sports())
    rows.extend(_films_and_ott())
    rows.extend(_studio_animation_and_tv())
    return rows


def historical_events() -> list[dict]:
    """Industry, fan, sports, esports, showcase, film, and OTT events 2022–2026."""
    return _records()


def historical_adaptations() -> list[dict]:
    """Film / OTT rows in the adaptations schema, derived from the event registry."""
    out: list[dict] = []
    for row in _records():
        if row["event_type"] not in MEDIA_EVENT_TYPES:
            continue
        medium = {
            "Theatrical Film": "Live-action theatrical film",
            "Animated Film": "Animated theatrical film",
            "OTT Film": "Streaming film",
            "OTT Series": "Live-action streaming series",
            "Animated Series": "Animated streaming series",
            "Anime Series": "Anime streaming series",
            "Podcast / Audio": "Scripted audio drama / podcast",
            "OTT Special": "Streaming special",
        }[row["event_type"]]
        out.append(
            {
                "kind": "adaptation",
                "start_date": row["start_date"],
                "end_date": row["end_date"],
                "date_precision": "day",
                "ip_adaptation": row["event"],
                "medium": medium,
                "distributor": row.get("organizer") or "",
                "related_game": row.get("related_game") or "",
                "date_status": "Confirmed",
                "wikipedia_url": row.get("wikipedia_url") or "",
                "source": "historical_registry",
                "confirmation": "confirmed",
                "format": medium,
                "scope": "global",
                "release_channel": medium,
            }
        )
    return out


